public class Driver{public static void main(String[] args){fixtures.Dep.failInit=Boolean.parseBoolean(args[1]);StringBuilder values=new StringBuilder();for(int i=0;i<2;i++){if(i!=0)values.append(",");try{int v;switch(args[0]){case "readFinal":v=fixtures.Reader.readFinal();break;case "unusedFinal":v=fixtures.Reader.unusedFinal();break;case "read":v=fixtures.Reader.read();break;case "write":v=fixtures.Reader.write();break;default:v=fixtures.Reader.unused();}values.append(v);}catch(Throwable e){values.append(e.getClass().getName());}}System.out.println(values+";"+String.join(",",fixtures.Dep.events));}}
